-- 1. Penyesuaian tipe kolom AbsenID agar menerima format string dari Google Sheets (ABS...)
ALTER TABLE public.absen_sholat ALTER COLUMN absen_id TYPE VARCHAR(100);
ALTER TABLE public.absen_sholat ALTER COLUMN absen_id SET DEFAULT 'ABS' || (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT::TEXT;

-- 2. Kebijakan Storage Bucket untuk Upload Foto Selfie
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public Upload Foto Absen' AND tablename = 'objects') THEN
    CREATE POLICY "Public Upload Foto Absen" ON storage.objects FOR INSERT TO public WITH CHECK (bucket_id = 'foto_absen');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public Read Foto Absen' AND tablename = 'objects') THEN
    CREATE POLICY "Public Read Foto Absen" ON storage.objects FOR SELECT TO public USING (bucket_id = 'foto_absen');
  END IF;
END $$;

-- 3. DATA PENGATURAN SISTEM (45 Baris)

Waktu sholat *{sholat}* sedang berlangsung.
Segera laksanakan sholat dan lakukan absen di aplikasi SIIP (deskripsi grup WA PAI).
“Ketika hati lelah, bersujudlah.”

_(Pesan otomatis pengingat ibadah)_', 'Pengaturan sistem'),
  ('wa_target_mode', 'kustom', 'Pengaturan sistem'),
  ('wa_target_kelas', '', 'Pengaturan sistem'),
  ('wa_target_nomor', '', 'Pengaturan sistem')
ON CONFLICT (parameter) DO UPDATE SET nilai = EXCLUDED.nilai;

-- 4. DATA SISWA (180 Siswa)
ON CONFLICT (nis) DO UPDATE SET
  nama = EXCLUDED.nama,
  kelas = EXCLUDED.kelas,
  jurusan = EXCLUDED.jurusan,
  jk = EXCLUDED.jk,
  status = EXCLUDED.status,
  password = EXCLUDED.password,
  no_hp = EXCLUDED.no_hp;

